	 * Reloads the model of the table in this panel.  This differs from {@link #updateModel()} in
	 * that it forces any existing data to be thrown out.
	 */
	void reloadModel() {
		tableModel.fullReload();
	}

	bool isBusy() {
		return tableModel.isBusy();
	}

	void remove(List<LocationReference> refs) {
		foreach (LocationReference lr in refs) {
			tableModel.removeObject(lr);
		}
	}

	List<LocationReference> getSelectedReferences() {
		List<LocationReference> list = new();
		int[] rows = table.getSelectedRows();
		foreach (int row in rows) {
			LocationReference lr = tableModel.getRowObject(row);
			list.add(lr);
		}
		return list;
	}

